svg.script:
(function(){
  var pupils=[].slice.call(document.querySelectorAll('.av-pupil'));
  function place(px,py){
    pupils.forEach(function(p){
      var eye=document.getElementById(p.getAttribute('data-eye'));
      var r=eye.getBoundingClientRect();
      var cx=r.left+r.width/2, cy=r.top+r.height/2;
      var nx=(px-cx)/(r.width/2), ny=(py-cy)/(r.height/2);
      var d=Math.sqrt(nx*nx+ny*ny); if(d>1){nx/=d;ny/=d;}
      var tx=+p.getAttribute('data-tx'), ty=+p.getAttribute('data-ty');
      p.setAttribute('transform','translate('+(nx*tx).toFixed(2)+','+(ny*ty).toFixed(2)+')');
    });
  }
  window.avLook=place; window.addEventListener('pointermove',function(e){place(e.clientX,e.clientY);try{if(window.frameElement&&window.parent&&window.parent.avLookAll){var fr=window.frameElement.getBoundingClientRect();window.parent.avLookAll(e.clientX+fr.left,e.clientY+fr.top,null);}}catch(err){}});
})();
